#include <bits/stdc++.h>
using namespace std;

long long reflect_num(long long n) {
    if (n == 0) return 0;
    long long res = 0;
    long long p = 1;
    while (n > 0) {
        int d = n % 10;
        int rd = 9 - d;
        res += 1LL * rd * p;
        p *= 10;
        n /= 10;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long l, r;
    if (!(cin >> l >> r)) return 0;

    long long ans = 0;

    auto update = [&](long long n) {
        if (n < l || n > r) return;
        long long psi = reflect_num(n);
        long long w = n * psi;
        if (w > ans) ans = w;
    };

    // brute force if range is small
    if (r - l <= 2000000) {
        for (long long n = l; n <= r; ++n) {
            update(n);
        }
        cout << ans << '\n';
        return 0;
    }

    // general heuristic: check boundaries and numbers of form 10^k, 10^k-1, etc.
    update(l);
    update(r);

    // generate powers of 10 within [1, 1e9]
    for (long long p = 1; p <= 1000000000LL; p *= 10) {
        long long candidates[] = {p, p - 1, p + 1};
        for (long long x : candidates) {
            update(x);
        }
    }

    // also check around l and r locally
    for (long long d = -100; d <= 100; ++d) {
        update(l + d);
        update(r + d);
    }

    cout << ans << '\n';
    return 0;
}

