#include <bits/stdc++.h>
using namespace std;

long long reflect_num(long long n) {
    if (n == 0) return 0;
    string s = to_string(n);
    for (char &c : s) {
        int a = c - '0';
        c = char('0' + (9 - a));
    }
    long long res = 0;
    for (char c : s) {
        res = res * 10 + (c - '0');
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long l, r;
    if (!(cin >> l >> r)) return 0;

    long long ans = 0;

    auto upd = [&](long long n) {
        if (n < l || n > r) return;
        long long psi = reflect_num(n);
        long long w = n * psi;
        if (w > ans) ans = w;
    };

    for (int d = 1; d <= 10; ++d) {
        long long base = 1;
        for (int i = 1; i < d; ++i) base *= 10;

        for (int pos = 0; pos < d; ++pos) {
            long long n = 0;
            long long pow10 = 1;
            for (int i = 0; i < d; ++i) {
                int digit = (i == pos ? 4 : 9);
                n += digit * pow10;
                pow10 *= 10;
            }
            upd(n);
        }
    }

    for (long long n = max(l, 1LL); n <= min(r, l + 1000); ++n) upd(n);
    for (long long n = max(l, r - 1000); n <= r; ++n) upd(n);

    cout << ans << '\n';
    return 0;
}
